// Loop-Invariant Code Motion (LICM)
// Compiler moves computation (A * B) outside the loop
float compute_invariant(float A, int N, float B) {
    float result = 0.0;
    // Before optimization:
    // for (int i=0; i<N; ++i) { result += A * B + i; }

    float temp = A * B; // Moved out by LICM
    for (int i = 0; i < N; ++i) {
        result += temp + i;
    }
    return result;
}

// Common Subexpression Elimination (CSE)
// Avoiding recalculation of identical terms
void calculate(int a, int b, int c, int* X, int* Y) {
    // Original code:
    // *X = (a + 42) * b;
    // *Y = c / (a + 42);

    int subexpr = a + 42; // Calculated once by CSE
    *X = subexpr * b;
    *Y = c / subexpr;
}

// Vectorization Hint (SIMD)
// Compiler transforms loop for parallel processing
#define N 1024
float A[N], B[N], C[N];

#pragma omp simd
for (int i = 0; i < N; ++i) {
    C[i] = A[i] * 2.0 + B[i];
}
// Requires optimization flags like -O3 and -fopenmp
